\label{prop:screen}
Assume that a fully labeled iid pilot of $n_0$ queries from $P$, independent
of subsequent data, is available, and let
$\widehat{F}_0(S)=n_0^{-1}\sum_{i=1}^{n_0}h_S(Q_i^{(0)})$ for all $S\in\mathcal{H}_B$.
For $0<\alpha_s<1$, set
\begin{equation}\label{eq:pilot-radius}
 r_0=\sqrt{\frac{\log(2|\mathcal{H}_B|/\alpha_s)}{2n_0}}.
\end{equation}
After choosing any pilot-measurable $\widehat{S}\in\mathcal{H}_B$, let
\begin{equation}\label{eq:pilot-screen}
 \mathcal{C}=\{\widehat{S}\}\cup
 \left\{T\in\mathcal{H}_B:\widehat{F}_0(T)-\widehat{F}_0(\widehat{S})+2r_0\ge0\right\}.
\end{equation}
Then \eqref{eq:screen} holds.

\label{lem:increment}
Under Assumption~\ref{ass:audit}, for every pre-audit edge $e=(U,V)$
and every $t>0$, conditional on the pre-audit information and counts,
\begin{equation}\label{eq:bernstein-edge}
 \mathbb{P}\left\{Z_U-Z_V>
 \sqrt{2d_2^2(e)t}+\frac13d_\infty(e)t
 \ \middle|\ \text{pre-audit information, counts}\right\}\le e^{-t}.
\end{equation}
No assumption of independence across different edges is needed.

\label{th:chain}
Assume the model of Section~\ref{sec:model}. Choose numbers
$\alpha_1,\ldots,\alpha_L>0$ with
$\sum_{\ell=1}^L\alpha_\ell=\alpha_a<1$ and let
\begin{equation}\label{eq:tlevel}
 t_\ell=\log\frac{|\mathcal{E}_\ell|}{\alpha_\ell}.
\end{equation}
Suppose that for all distinct edges $e\in\mathcal{E}$ there are nonnegative,
possibly audit-data-dependent random variables $\overline{v}_e,\overline{b}_e$ such that
\begin{equation}\label{eq:edge-calibration}
 \mathbb{P}\left\{\forall e\in\mathcal{E}:\;
 d_2^2(e)\le\overline{v}_e,\quad d_\infty(e)\le\overline{b}_e
 \ \middle|\ \text{pre-audit information, counts}\right\}\ge1-\alpha_v.
\end{equation}
Define the path-dependent radius
\begin{equation}\label{eq:radius}
 \mathfrak R(T)=\sum_{\ell=1}^L
 \mathbf{1}\{e_\ell(T)\in\mathcal{E}_\ell\}
 \left\{\sqrt{2\overline{v}_{e_\ell(T)}t_\ell}
       +\frac13\overline{b}_{e_\ell(T)}t_\ell\right\}.
\end{equation}
Then, conditionally on the pre-audit information and counts,
\begin{equation}\label{eq:main-ineq}
 \mathbb{P}\left\{\forall T\in\mathcal{C}:\ Z_T\le\mathfrak R(T)
 \ \middle|\ \text{pre-audit information, counts}\right\}
 \ge1-\alpha_a-\alpha_v.
\end{equation}
The result remains valid when $\mathcal{C}$, $\widehat{S}$, and the network are
arbitrarily data-dependent through the independent pilot and unlabelled
information.

\label{lem:empbern}
Let $Y_1,\ldots,Y_n$ be iid in $[a,b]$ for $n\ge2$ and let
$s_n^2$ be their unbiased sample variance. For $0<\delta<1$,
\begin{equation}\label{eq:empbern}
 \mathbb{P}\left\{\mathbb{E} Y-\overline{Y}>
 \sqrt{\frac{2s_n^2\log(2/\delta)}n}
 +\frac{7(b-a)\log(2/\delta)}{3(n-1)}\right\}\le\delta.
\end{equation}
The same assertion holds with $\overline{Y}-\mathbb{E} Y$ in place of
$\mathbb{E} Y-\overline{Y}$.

\label{lem:residual}
Let $E=|\mathcal{E}|\ge1$. Set
\[
 t_v=\log\frac{2HE}{\alpha_v},\qquad
 v^+_{h,e}=\min\left\{1,\ \overline{Y}_{h,e}
       +\sqrt{\frac{2s_{Y,h,e}^2t_v}{n_h}}
       +\frac{7M_{h,e}t_v}{3(n_h-1)}\right\}.
\]
Under Assumptions~\ref{ass:audit} and~\ref{ass:pred},
\begin{equation}\label{eq:vplus-valid}
 \mathbb{P}\left\{\forall h,e:\quad v_{h,e}\le v^+_{h,e}
 \ \middle|\ \text{pre-audit information, counts}\right\}
 \ge1-\alpha_v.
\end{equation}

\label{th:direct-empirical}
Assume the stratified, label-ignorable audit design
(Assumption~\ref{ass:audit}) and a pre-audit network as in
Definition~\ref{def:network}. For every $h$ and every distinct directed
edge $e\in\mathcal{E}$, let
$\overline{G}_{h,e}=n_h^{-1}\sum_{i=1}^{n_h}G_e(Q_{h,i})$, and let
$s_{h,e}^2$ be the unbiased sample variance of
$G_e(Q_{h,1}),\ldots,G_e(Q_{h,n_h})$. Let $\bar b_{h,e}\in[0,2]$ be the
known pre-audit constants of Theorem~\ref{th:empirical}, satisfying
$\operatorname{osc}_h(G_e)\le\bar b_{h,e}$. For $\sum_\ell\alpha_\ell=\alpha_a<1$ set
\begin{equation}\label{eq:one-stage-t}
 t_\ell^{\mathrm{EB}}=\log\frac{2H|\mathcal{E}_\ell|}{\alpha_\ell}
\end{equation}
and define
\begin{equation}\label{eq:one-stage-radius}
 \mathfrak R_{\mathrm{EB}}(T)
 =\sum_{\ell=1}^L\mathbf{1}\{e_\ell(T)\in\mathcal{E}_\ell\}
 \sum_{h\in\mathcal{S}}\widehat{\pi}_h
 \left\{\sqrt{\frac{2s_{h,e_\ell(T)}^2
                            t_\ell^{\mathrm{EB}}}{n_h}}
      +\frac{7\bar b_{h,e_\ell(T)}t_\ell^{\mathrm{EB}}}{3(n_h-1)}
 \right\}.
\end{equation}
Then, conditionally on the pre-audit information and counts,
\begin{equation}\label{eq:one-stage-bound}
 \mathbb{P}\left\{\forall T\in\mathcal{C}:\ Z_T\le
    \mathfrak R_{\mathrm{EB}}(T)
    \ \middle|\ \text{pre-audit information, counts}\right\}
 \ge1-\alpha_a.
\end{equation}
In particular, this certificate requires neither pre-audit
residual predictors (Assumption~\ref{ass:pred}) nor the separate
calibration budget $\alpha_v$.

\label{lem:propweights}
Under Assumptions~\ref{ass:unlabelled} and~\ref{ass:audit}, with probability
at least $1-\alpha_\pi-\alpha_g$, simultaneously for all $T\in\mathcal{C}$,
\begin{equation}\label{eq:pi-correction}
 \left|\sum_h(\pi_h-\widehat{\pi}_h)\mu_{h,T}\right|
 \le e_\pi\sum_{h=1}^{H-1}\rho_{h,T}.
\end{equation}

\label{lem:activity}
Let $j,k\notin R$, let $S=R\cup\{j\}$, $T=R\cup\{k\}$, and suppose
$\sup_{q\in\mathcal{Q}}|r_j(q)-r_k(q)|\le\varepsilon$. Define the activity event
\begin{equation}\label{eq:activity-def}
 A_{j,k,R}(q)=\mathbf{1}\{\max(r_j(q),r_k(q))>a_R(q)\},
\end{equation}
and $a_h=\mathbb{P}\{A_{j,k,R}(Q)=1\mid X=h\}$. Then for every $q$,
\begin{equation}\label{eq:activity-bound}
 |h_S(q)-h_T(q)|\le\varepsilon A_{j,k,R}(q),
\end{equation}
and, for every stratum $h$,
\begin{equation}\label{eq:activity-var}
 \operatorname{Var}(h_S(Q)-h_T(Q)\mid X=h)\le\varepsilon^2a_h,
 \qquad \operatorname{osc}_h(h_S-h_T)\le2\varepsilon.
\end{equation}
Consequently the edge $e=(S,T)$ obeys
\begin{equation}\label{eq:activity-d2}
 d_2^2(e)\le\varepsilon^2\sum_h\frac{\widehat{\pi}_h^2}{n_h}a_h,
 \qquad d_\infty(e)\le2\varepsilon\max_h\frac{\widehat{\pi}_h}{n_h}.
\end{equation}

\label{cor:twolevel}
Suppose the $J=|\mathcal{C}|-1\ge2$ nontrivial competitors admit $K_0$ distinct
representatives, $1\le K_0<J$, and a map
$c:\mathcal{C}\setminus\{\widehat{S}\}\to\{1,\ldots,K_0\}$
such that every candidate $T\ne\widehat{S}$ is associated with a
representative $V_{c(T)}$ and
\begin{equation}\label{eq:uniform-clusters}
 \sup_{q\in\mathcal{Q}}|h_T(q)-h_{V_{c(T)}}(q)|\le\varepsilon,
 \qquad 0\le\varepsilon\le1.
\end{equation}
Assume each representative belongs to $\mathcal{C}$, and use the two-level
network $\widehat{S}\to V_{c(T)}\to T$ for $T\ne\widehat{S}$, while the
selected set follows the constant path
$\widehat{S}\to\widehat{S}\to\widehat{S}$. The first-level network includes
$\widehat{S}$ and all representatives. Define
\begin{equation}\label{eq:q-b}
 q_n=\sum_h\frac{\widehat{\pi}_h^2}{n_h},\qquad
 b_n=2\max_h\frac{\widehat{\pi}_h}{n_h},\qquad
 L_n(t)=\sqrt{2q_nt}+\frac13b_nt.
\end{equation}
For $\alpha_1+\alpha_2=\alpha_a$, the uniform two-level radius is
\begin{equation}\label{eq:two-level-radius}
 C_{\mathrm{chain}}
 =L_n\left(\log\frac{K_0}{\alpha_1}\right)
  +\varepsilon L_n\left(\log\frac{J}{\alpha_2}\right).
\end{equation}
The flat cardinality-based direct Bernstein radius is
\begin{equation}\label{eq:flat-radius}
 C_{\mathrm{flat}}=L_n\left(\log\frac{J}{\alpha_a}\right).
\end{equation}
Whenever
\begin{equation}\label{eq:strict-gain}
 0\le\varepsilon<
 \frac{L_n(\log(J/\alpha_a))
             -L_n(\log(K_0/\alpha_1))}
      {L_n(\log(J/\alpha_2))},
\end{equation}
with positive numerator, one has
$C_{\mathrm{chain}}<C_{\mathrm{flat}}$.
Both bounds apply simultaneously to all candidates with conditional
failure probability at most $\alpha_a$.
